import{_ as n,o as a,c as e,a2 as p}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"Open Cube OS 架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh/root/ARCHITECTURE.md","filePath":"zh/root/ARCHITECTURE.md"}'),o={name:"zh/root/ARCHITECTURE.md"};function c(l,s,t,i,r,d){return a(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="open-cube-os-架构" tabindex="-1">Open Cube OS 架构 <a class="header-anchor" href="#open-cube-os-架构" aria-label="Permalink to &quot;Open Cube OS 架构&quot;">​</a></h1><p>本文档描述 3.0.0-WP-l1apps-merge 时点的代码树——下文点名的 每个组件都是你能打开的真实文件。行数与逐目录明细在 <code>docs/data/stats.json</code>（重新生成：<code>make api-docs</code>）。</p><h2 id="两个环" tabindex="-1">两个环 <a class="header-anchor" href="#两个环" aria-label="Permalink to &quot;两个环&quot;">​</a></h2><p>Open Cube OS 是一个双环系统：</p><ul><li><strong>L0——提供服务。</strong> 纯服务内核：核心机制、驱动、根 服务和接口面。3.0.0-WP03 彻底删除了 L0 用户面——<code>oc&gt;</code> shell、每条 shell 命令、TUI 框架和输入法引擎都不见了； L0 在 <code>L0 ready, waiting for L1</code> 完成启动，把机器交给默认 的 Ring-3 入口。</li><li><strong>L1——使用服务。</strong> 经扩展面（<code>SYS_L1SVC</code> 操作表 和经典 syscall ABI）触达 L0 能力的 Ring-3 用户应用。 3.0.0-WP04 把每条命令都移进了 L1：<strong><code>ocos/l1apps/</code> 下的 284 个程序</strong>（含 8 个合并大应用）——一条命令 = 一个应用 = 一个文件夹。默认启动项是 Ring-3 的 <code>ush</code> shell （<code>ocos/kernel/core_boot_l1launch.c</code> 中的 <code>OC_L1_APP_DECL(&quot;ush&quot;, ..., dflt=1)</code>）；<strong>296 条命令 = 284 个 注册表应用 + 12 个 ush 内建，L0 里零条</strong>。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>              OCBL - the in-tree bootloader (hybrid BIOS + UEFI ISO)</span></span>
<span class="line"><span>              512-byte real-mode stage 1 (El Torito / MBR) or the EFI</span></span>
<span class="line"><span>              entry -&gt; 16 -&gt; 32 -&gt; 64-bit long mode, dynamic disk scan,</span></span>
<span class="line"><span>              boot menu with a 10 s countdown (no GRUB in the chain)</span></span>
<span class="line"><span>        +-------------------------+-------------------------+</span></span>
<span class="line"><span>        |              ocos/kernel/core_boot_entry.S                  |</span></span>
<span class="line"><span>        |  32-bit entry -&gt; GDT -&gt; 2 MiB identity map of    |</span></span>
<span class="line"><span>        |  the first 4 GiB -&gt; PAE+LME+PGE -&gt; long mode     |</span></span>
<span class="line"><span>        +---------------------------------------------------+</span></span>
<span class="line"><span>                               |  kmain (ocos/kernel/core_boot_main.c)</span></span>
<span class="line"><span>        +-------------------------+-------------------------+</span></span>
<span class="line"><span>        |  PHASE 1  kernel core mechanisms                  |</span></span>
<span class="line"><span>        |    core/console (serial/fb platform text layer),  |</span></span>
<span class="line"><span>        |    IDT/PIC/exceptions, PIT, PMM/VMM/heap,         |</span></span>
<span class="line"><span>        |    scheduler/sync, userspace, registry,           |</span></span>
<span class="line"><span>        |    ACPI/PCIe/watchdog-hw/chipset, RTC/HPET        |</span></span>
<span class="line"><span>        |  PHASE 2  drivers + driver-free services          |</span></span>
<span class="line"><span>        |    VFS + ramfs (driver-free); block/USB/wireless/ |</span></span>
<span class="line"><span>        |    SD/BT/camera/misc driver families              |</span></span>
<span class="line"><span>        |  PHASE 3  driver-dependent services               |</span></span>
<span class="line"><span>        |    FAT/exFAT/ext4 + config + A/B (after block),   |</span></span>
<span class="line"><span>        |    wireless (after fs-mounted firmware),          |</span></span>
<span class="line"><span>        |    net (after NIC), snd (after the snd family)    |</span></span>
<span class="line"><span>        |  PHASE 4  interfaces ready                        |</span></span>
<span class="line"><span>        |    crash dump/crashlog/soft wdt, health monitor,  |</span></span>
<span class="line"><span>        |    update check, the OCIRE embed confirmation     |</span></span>
<span class="line"><span>        +---------------------------------------------------+</span></span>
<span class="line"><span>                               |</span></span>
<span class="line"><span>                     &quot;L0 ready, waiting for L1&quot;</span></span>
<span class="line"><span>                               |</span></span>
<span class="line"><span>                    l1 launcher -&gt; ush (ring 3)</span></span>
<span class="line"><span>                               |</span></span>
<span class="line"><span>          exit / failure -&gt; L0 halts honestly (reboot or the</span></span>
<span class="line"><span>          OCBL menu; the 2.x oc&gt; recovery fallback is gone)</span></span></code></pre></div><p>（启动会为中段各阶段打印 <code>boot chain N/4</code> 标记； <code>tools/check_deps.py</code> 为下面的层方向把关。）</p><h2 id="l0-树-3-0-0-wp03-布局" tabindex="-1">L0 树（3.0.0-WP03 布局） <a class="header-anchor" href="#l0-树-3-0-0-wp03-布局" aria-label="Permalink to &quot;L0 树（3.0.0-WP03 布局）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ocos/kernel/</span></span>
<span class="line"><span>  boot/     the composition root: boot.S, long mode entry, the</span></span>
<span class="line"><span>            multiboot2 header/stub, kmain.c, the L1 launcher and the</span></span>
<span class="line"><span>            boot self-tests. May depend on every layer.</span></span>
<span class="line"><span>  core/     kernel mechanisms: scheduling, sync, timers, usermode,</span></span>
<span class="line"><span>            the panic slots (arch_exceptions), the declaration</span></span>
<span class="line"><span>            registry, the captured-output primitive, mem/, lib/</span></span>
<span class="line"><span>            (string/log/klog-ring/config-kv), console/ (the mb2</span></span>
<span class="line"><span>            framebuffer platform text layer), arch/{x86_64,arm64,</span></span>
<span class="line"><span>            riscv} and generated/.  Depends on nothing above it.</span></span>
<span class="line"><span>  drivers/  hardware drivers, one folder per family (block, nic,</span></span>
<span class="line"><span>            snd, usb, input, pci, acpi, i2c, time, wireless,</span></span>
<span class="line"><span>            bluetooth, sd, camera, misc, scsi).  No services</span></span>
<span class="line"><span>            dependencies.</span></span>
<span class="line"><span>  services/ root services - the folder is the interface facet:</span></span>
<span class="line"><span>            fs block net audio font encoding display loader</span></span>
<span class="line"><span>            selfhost ocembed | sysapi ipc klog health crash</span></span>
<span class="line"><span>            (+ time power crypto camera usb bodies).  May depend on</span></span>
<span class="line"><span>            core/ and drivers/ (and, where a real dependency</span></span>
<span class="line"><span>            exists, on other services - fs before selfhost, for</span></span>
<span class="line"><span>            example).</span></span>
<span class="line"><span>ocos/l1apps/     the ring-3 world: 275 programs (242 app folders + 8 flat</span></span>
<span class="line"><span>            .c + 25 flat .asm) - ush (the only OC_L1_APP_DECL default</span></span>
<span class="line"><span>            entry), the TUI desktop family, the editor, the Chinese</span></span>
<span class="line"><span>            console + IME, and one command per app (built by</span></span>
<span class="line"><span>            \`make l1apps\`).</span></span>
<span class="line"><span>ocbl/       OCBL, the in-tree bootloader (BIOS stage 1 + EFI entry,</span></span>
<span class="line"><span>            the boot menu, the ocbl-install target) - a separate</span></span>
<span class="line"><span>            freestanding build (ocbl/ocbl.mk). NOT part of L0.</span></span>
<span class="line"><span>ocire/      the independent recovery kernel (a separate freestanding</span></span>
<span class="line"><span>            binary, own build in ocire/ocire.mk).  NOT part of L0.</span></span></code></pre></div><p><strong>依赖规则</strong>（由 <code>tools/check_deps.py</code> 强制，跑在测试矩阵中）： <code>core/</code> 不得依赖 <code>drivers/</code> 或 <code>services/</code>；<code>drivers/</code> 不得依赖 <code>services/</code>。WP-03 G5 为此要求的倒置：平台控制台栈住在 <code>core/console</code>；klog 环是核心机制，盘上汇聚点作为发射钩子 安装自 <code>services/klog</code>；崩溃捕获住在 <code>services/crash</code>，把自己的 处理程序装进核心持有的 panic 槽；配置存储把键值机制留在 核心，fs 后端安装自 <code>services/fs</code>。</p><h2 id="加一个文件即扩展" tabindex="-1">加一个文件即扩展 <a class="header-anchor" href="#加一个文件即扩展" aria-label="Permalink to &quot;加一个文件即扩展&quot;">​</a></h2><p>没有东西通过运行时调用注册进全局表。驱动、服务或 L1 应用 通过 <code>OC_*_DECL</code> 宏（<code>core_registry.h</code>）在<strong>实现它的那个 文件里</strong>声明身份；每个宏把一个 const 描述符放进专门的 链接器节（<code>.oc_drvs</code>、<code>.oc_svcs</code>、<code>.oc_apps</code>）， <code>core_registry_collect()</code> 在启动时走查节边界。新增一个驱动 或服务 = 在正确的文件夹里加一个 <code>.c</code> 文件再加一行声明—— 不改启动文件，没有注册调用点（G3 证据中实测：一个带 <code>OC_DRIVER_DECL</code> 的新文件在运行时被收集，随后移除）。</p><p>v1 的 register 类 L1 接口（<code>driver_block_register</code>、 <code>driver_nic_register</code>、……）随节机制一同消亡；它们的操作类 兄弟（read/write/send/recv/…）仍是表面（完整表格和 v1-&gt;v2-&gt;v3 命运记录见 INTERFACES.md）。</p><h2 id="接口面" tabindex="-1">接口面 <a class="header-anchor" href="#接口面" aria-label="Permalink to &quot;接口面&quot;">​</a></h2><p>Ring 3 经两扇门触达 L0：</p><ul><li>经典 syscall ABI （<code>ocos/kernel/services/sysapi/core_syscall.h</code>， 54 个系统调用），含 <code>SYS_L1SVC(110)</code>： <code>(category, op, arg, out, cap)</code> 由注册表路由到所属服务的 <code>l1_dispatch</code>。</li><li>categories/ops 是 <code>ocos/kernel/services/sysapi/l1svc_defs.h</code> 中冻结的 ABI 表： <strong>20 个类别 / 190 个编号条目</strong>（类别号 -&gt; 所属的 services/ 文件夹；类别 18 &quot;ocire&quot; 是声明的例外——OCIRE 日志代理契约 的 ABI 名，由 <code>services/ocembed/</code> 实现）。操作是纯 ASCII 文本渲染器——Ring-3 侧不格式化任何东西。</li></ul><h2 id="启动状态监视器-3-0-0-wp07a" tabindex="-1">启动状态监视器（3.0.0-WP07a） <a class="header-anchor" href="#启动状态监视器-3-0-0-wp07a" aria-label="Permalink to &quot;启动状态监视器（3.0.0-WP07a）&quot;">​</a></h2><p>内核运行期间 OCBL 无法执行，因此 WP07a 启动状态监视器用 一台硬件看门狗中继（6300ESB，与 OCIRE 监督循环所用的同一 PCI 设备）强制启动超时：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OCBL arm(30s) -&gt; handoff -&gt; kernel stage N: write stage + arm(next</span></span>
<span class="line"><span>budget) -&gt; ... -&gt; L1_READY: 1 Hz tick pets the 15 s runtime budget</span></span>
<span class="line"><span>                |</span></span>
<span class="line"><span>                v (a hang stops the feeding)</span></span>
<span class="line"><span>6300ESB resets the machine (warm reset, DRAM kept)</span></span>
<span class="line"><span>                |</span></span>
<span class="line"><span>OCBL boots again: reads the state area -&gt; silence &gt;= 8 s and no</span></span>
<span class="line"><span>CLEAN marker -&gt; JUDGED: writes the BOOT_FAILED record (stall point,</span></span>
<span class="line"><span>timestamp, measured silence) -&gt; screen notice -&gt; 8042 pulse</span></span>
<span class="line"><span>                |</span></span>
<span class="line"><span>OCBL boots again: pending unrouted record -&gt; auto-boots OCIRE</span></span>
<span class="line"><span>                |</span></span>
<span class="line"><span>OCIRE: reads the record -&gt; prints the stall point + repair advice</span></span></code></pre></div><p>契约住在 <code>include/ocbl_state.h</code>（OCBL、OCOS 和 OCIRE 逐字节 共享）：</p><ul><li><strong>状态区</strong>位于 0x98000——内核正在做什么（阶段、心跳、 最近一次进展的 RTC 时钟）。内核只写它（盲写，从不回读）； OCBL 读写；OCIRE 只读。L1 应用够不到它：这些页面位于每个 用户地址空间的管理者专属半区（在 L1_READY 由一次 CR3 走查 + badapp 金丝雀类实测验证）。</li><li><strong>保留区</strong>位于 0x9B000——事后启动记录（BOOT_FAILED 与 USER_REQUEST、停滞阶段、判定时间戳、测得的静默、反码 校验和）。它在热复位中存活（这两个地址是 QEMU/SeaBIOS 复位擦除中经实证的幸存孤岛——见 <code>evidence/3_0_0_WP07a/</code>）；冷启动会清掉它，且每个读取者 都先验证魔数。</li><li><strong>六个状态点</strong>：KM_AIN_ENTERED（kmain 入口）、 SCHED_READY（核心机制就绪）、DRIVERS_READY（驱动家族已 探测）、SERVICES_READY（根服务就绪）、L1_LAUNCHED（ush 已启动）、L1_READY（ush 在服务——它的第一次系统调用）。</li><li><strong>阶段预算</strong>：30 秒（启动开始 -&gt; 阶段 1）、中段每阶段 10 秒、30 秒（L1_LAUNCHED -&gt; L1_READY）、15 秒运行时 心跳。</li><li><strong>判定</strong>：OCBL 计算静默时长（RTC 现值减去内核最近一次 进展）；无 CLEAN 标记且 &gt;= 8 秒 = 判定失败（健康的启动 每秒都有进展，因此手动热复位测得 &lt; ~4 秒，不算失败）。</li><li><strong>干净重启</strong>：内核在有意的 8042 重启之前把状态区标记为 CLEAN，因此正常的 <code>reboot</code> 永不产生失败记录。</li><li><strong>用户请求</strong>：在 OCBL 菜单中选择 OCIRE 条目会写入 USER_REQUEST 记录——这正是 OCIRE 报告时区分的两种情形 （&quot;requested by the user&quot; 与带修复建议的判定失败）。</li></ul><p>整条链由 <code>tools/wp07a_state_e2e.py</code> 实测驱动（真实看门狗 复位、真实 8042 脉冲、两种记录、每个阶段预算、运行时 挂起、手动复位甄别）；誊录归档在 <code>evidence/3_0_0_WP07a/</code> 之下。</p><h2 id="ocire-内嵌-3-0-0-wp03-g4" tabindex="-1">OCIRE 内嵌（3.0.0-WP03 G4） <a class="header-anchor" href="#ocire-内嵌-3-0-0-wp03-g4" aria-label="Permalink to &quot;OCIRE 内嵌（3.0.0-WP03 G4）&quot;">​</a></h2><p>当 OCIRE 恢复监督者（见 <code>ocire/</code>）经 kexec 把机器交给 OCOS 时，它在命令行上传递启动事实 （<code>oc.mb= oc.log= oc.logsecs= oc.wdt= oc.agent=1</code>）并把它的 日志代理作为 multiboot2 模块挂载。<code>services/ocembed/</code> 在 OCOS 侧闭合回路：它解析事实、向恢复邮箱写 SIGNAL_OK、在 受监督的 60 秒窗口内解除 i6300esb 看门狗布防、把代理生成 为受保护的 <code>ocire_guard</code> 进程（kill 被 sys_kill 拒绝）、服务 guard 专属的 <code>L1SVC_CAT_OCIRE</code> 通道（启动日志追加 + 内核 日志快照）并在恢复盘上布防整盘写保护。正常 OCBL 启动时 没有任何事实存在，服务保持休眠。五条回归性质（分区隔离、 启动信号、双向接口、进程保护、整盘硬保护）由 <code>tools/run_ocire_supervised_tests.py</code> 端到端测试。</p><h2 id="留下来的内核能力" tabindex="-1">留下来的内核能力 <a class="header-anchor" href="#留下来的内核能力" aria-label="Permalink to &quot;留下来的内核能力&quot;">​</a></h2><p>内核日志环（+ <code>/var/log/kernel.log</code> 汇聚点）、健康监视器 （1 秒采样 + 告警）、崩溃捕获（核心转储 + crashlog + panic 路径）、软看门狗槽和硬件看门狗（TCO/WDAT）都是 L0 侧 机制——过去驱动它们的 L0 COMMAND 条目随用户面一同消亡； 机制本身在启动时布防、可测试（测试组在 <code>evidence/3_0_0_wp03_*</code>）。</p>`,26)])])}const u=n(o,[["render",c]]);export{g as __pageData,u as default};
